// Generated by Claude Code
package ui;

import grading.execution.QuestionGradingResult;
import grading.progress.GradingStatus;
import grading.progress.StudentProgress;
import java.util.ArrayList;
import java.util.List;

/** Why a student needs a person to look at them, in a few words, for the results table. */
final class StudentIssues {

    private static final String SEPARATOR = "; ";

    private StudentIssues() {
    }

    /** Such as "Timeout Q2b; Similar to david.2024 (Q2a)"; empty when nothing needs checking. */
    static String reason(StudentProgress student) {
        List<String> reasons = new ArrayList<>();
        if (student.status() == GradingStatus.SKIPPED) {
            reasons.add("Identity not confirmed");
        }
        student.problems().forEach((question, status) -> reasons.add(problem(status) + " " + question));
        student.flags().forEach(flag ->
                reasons.add("Similar to " + flag.otherStudent() + " (" + flag.questionId() + ")"));
        return String.join(SEPARATOR, reasons);
    }

    private static String problem(QuestionGradingResult.Status status) {
        return switch (status) {
            case MISSING_FILES -> "Missing files";
            case COMPILATION_ERROR -> "Compile error";
            case COMPILATION_TIMEOUT -> "Compile timeout";
            case EXECUTION_TIMEOUT -> "Timeout";
            case OUTPUT_LIMIT_EXCEEDED -> "Too much output";
            case RUNTIME_ERROR -> "Crashed";
            case INVALID_SCORE -> "No score";
            case GRADING_ERROR -> "Grading error";
            case GRADED -> "Graded";
        };
    }
}
